from pathlib import Path
import re, zipfile, shutil
root=Path('/mnt/data/ngwork/nextgen-miner')
# create assets
out=root/'assets'/'operations'

out.mkdir(parents=True, exist_ok=True)
for typ, title in [('resources','Resources'),('workers','Workers'),('transport','Transport')]:
    for lvl in range(1,51):
        tier='Basic' if lvl<=10 else 'Industrial' if lvl<=20 else 'Advanced' if lvl<=30 else 'Elite' if lvl<=40 else 'Quantum'
        accent={'resources':'#22d3ee','workers':'#a78bfa','transport':'#f59e0b'}[typ]
        if typ=='resources':
            core=max(8,12+lvl//3); pipes=2+lvl//10
            body=f'<rect x="38" y="42" width="124" height="86" rx="16" fill="#0b1220" stroke="{accent}" stroke-width="4"/><rect x="52" y="58" width="96" height="50" rx="10" fill="#111827"/><circle cx="100" cy="83" r="{core}" fill="{accent}" opacity="0.85"/><g stroke="{accent}" stroke-width="4" opacity="0.75">' + ''.join(f'<path d="M {45+i*22} 42 V {20+(lvl%10)} H {60+i*12}"/>' for i in range(pipes)) + '</g>'
        elif typ=='workers':
            n=1+min(4,lvl//12)
            people=''.join(f'<circle cx="{58+i*28}" cy="66" r="8" fill="{accent}"/><rect x="{49+i*28}" y="76" width="18" height="28" rx="8" fill="#111827" stroke="{accent}" stroke-width="3"/>' for i in range(n))
            body=f'<rect x="34" y="36" width="132" height="98" rx="18" fill="#0b1220" stroke="{accent}" stroke-width="4"/><path d="M46 116 H154" stroke="{accent}" stroke-width="5"/><text x="100" y="126" text-anchor="middle" fill="#cbd5e1" font-size="9">WORKFORCE {lvl:02d}</text>{people}'
        else:
            length=80+lvl
            body=f'<rect x="28" y="58" width="{length}" height="52" rx="18" fill="#0b1220" stroke="{accent}" stroke-width="4"/><rect x="48" y="38" width="54" height="24" rx="8" fill="#111827" stroke="{accent}" stroke-width="3"/><circle cx="54" cy="118" r="12" fill="#111827" stroke="{accent}" stroke-width="4"/><circle cx="{34+length-18}" cy="118" r="12" fill="#111827" stroke="{accent}" stroke-width="4"/><path d="M110 70 H{20+length}" stroke="{accent}" stroke-width="5" opacity="0.7"/>'
        svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 150"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="{accent}" stop-opacity=".18"/><stop offset="1" stop-color="#0b1220"/></linearGradient></defs><rect width="200" height="150" rx="20" fill="url(#g)"/><text x="16" y="20" fill="#e2e8f0" font-size="11" font-family="Arial">{title.upper()}</text><text x="184" y="20" text-anchor="end" fill="{accent}" font-size="10" font-family="Arial">LV {lvl:02d} · {tier.upper()}</text>{body}</svg>'''
        (out/f'{typ}_level_{lvl:02d}.svg').write_text(svg)

# Patch operationView to show image and clearer progression
p=root/'app.js'
s=p.read_text()
old="""  const rows=operationUpgrades.filter(x=>x.operation_type===type).map(u=>{\n    const owned=operationPurchases.some(p=>p.operation_type===type&&Number(p.level)===Number(u.level));\n    const prevOK=u.level===1||operationPurchases.some(p=>p.operation_type===type&&Number(p.level)===Number(u.level)-1);\n    return `<div class=\"upgrade-row ${owned?'owned':''}\"><div class=\"upgrade-level\"><span>LEVEL ${u.level}</span><small>+${Number(u.capacity_bonus).toLocaleString()} capacity</small></div><div><strong>${Number(u.credit_cost).toLocaleString()} 💎</strong><small>${owned?'Owned':prevOK?'Next upgrade':'Locked — complete Level '+(u.level-1)}</small></div><button class=\"primary-btn small op-upgrade\" data-operation=\"${type}\" data-level=\"${u.level}\" ${owned||!prevOK?'disabled':''}>${owned?'Owned':prevOK?'Upgrade':'Locked'}</button></div>`\n  }).join('');\n"""
new="""  const rows=operationUpgrades.filter(x=>x.operation_type===type).map(u=>{\n    const owned=operationPurchases.some(p=>p.operation_type===type&&Number(p.level)===Number(u.level));\n    const prevOK=u.level===1||operationPurchases.some(p=>p.operation_type===type&&Number(p.level)===Number(u.level)-1);\n    const art=`assets/operations/${type}_level_${String(Number(u.level)).padStart(2,'0')}.svg`;\n    const tier=Number(u.level)<=10?'Common':Number(u.level)<=20?'Uncommon':Number(u.level)<=30?'Rare':Number(u.level)<=40?'Epic':'Legendary';\n    return `<div class=\"upgrade-row ${owned?'owned':''} ${prevOK&&!owned?'next-upgrade':''}\"><img class=\"operation-upgrade-art\" src=\"${art}\" alt=\"${esc(meta.title)} Level ${u.level}\" loading=\"lazy\"><div class=\"upgrade-level\"><span>LEVEL ${u.level}</span><small>${tier} · +${Number(u.capacity_bonus).toLocaleString()} capacity</small></div><div><strong>${Number(u.credit_cost).toLocaleString()} 💎</strong><small>${owned?'Owned':prevOK?'Next upgrade':'Locked — complete Level '+(u.level-1)}</small></div><button class=\"primary-btn small op-upgrade\" data-operation=\"${type}\" data-level=\"${u.level}\" ${owned||!prevOK?'disabled':''}>${owned?'Owned':prevOK?'Upgrade':'Locked'}</button></div>`\n  }).join('');\n"""
if old not in s:
    raise SystemExit('old operationView block not found')
p.write_text(s.replace(old,new))

# add CSS
css=root/'styles.css'
c=css.read_text()
c += '''\n.operation-upgrade-art{width:96px;height:72px;object-fit:cover;border-radius:12px;border:1px solid rgba(255,255,255,.08);background:#07101c}.upgrade-row.next-upgrade{box-shadow:0 0 0 1px rgba(34,211,238,.22),0 10px 30px rgba(34,211,238,.08)}\n@media(max-width:700px){.operation-upgrade-art{width:78px;height:58px}.upgrade-row{grid-template-columns:78px 1fr}.upgrade-row button{grid-column:1/-1}.upgrade-row>div:nth-of-type(2){text-align:right}}\n'''
css.write_text(c)

# create migration
mig=root/'supabase_infrastructure_bootstrap.sql'
mig.write_text('''-- NextGen Miner Infrastructure Bootstrap\n-- Apply only to a fresh NextGen Miner Supabase project after core tables are created.\n-- This file defines Resources, Workers, and Transport as independent level 1-50 systems.\n\ncreate table if not exists public.ng_infrastructure_levels (\n  operation_type text not null check (operation_type in ('resources','workers','transport')),\n  level integer not null check (level between 1 and 50),\n  tier text not null check (tier in ('Common','Uncommon','Rare','Epic','Legendary')),\n  capacity integer not null check (capacity > 0),\n  capacity_bonus integer not null check (capacity_bonus >= 0),\n  credit_cost numeric(30,0) not null check (credit_cost > 0),\n  efficiency_bps integer not null default 10000 check (efficiency_bps between 10000 and 50000),\n  active boolean not null default true,\n  primary key (operation_type, level)\n);\n\ncreate table if not exists public.ng_user_infrastructure (\n  user_id uuid primary key references auth.users(id) on delete cascade,\n  resources_level integer not null default 1 check (resources_level between 1 and 50),\n  workers_level integer not null default 1 check (workers_level between 1 and 50),\n  transport_level integer not null default 1 check (transport_level between 1 and 50),\n  updated_at timestamptz not null default now()\n);\n\ninsert into public.ng_infrastructure_levels(operation_type, level, tier, capacity, capacity_bonus, credit_cost, efficiency_bps)\nselect op, lvl,\n  case when lvl<=10 then 'Common' when lvl<=20 then 'Uncommon' when lvl<=30 then 'Rare' when lvl<=40 then 'Epic' else 'Legendary' end,\n  case op when 'resources' then round(1000*pow(1.22,lvl-1))::int when 'workers' then round(1*pow(1.20,lvl-1))::int when 'transport' then round(100*pow(1.22,lvl-1))::int end,\n  case op when 'resources' then round(1000*pow(1.22,lvl-1))::int when 'workers' then greatest(1,round(1*pow(1.20,lvl-1))::int) when 'transport' then round(100*pow(1.22,lvl-1))::int end,\n  round(case op when 'resources' then 1500*pow(1.23,lvl-1) when 'workers' then 1000*pow(1.22,lvl-1) else 1200*pow(1.23,lvl-1) end),\n  case when lvl<=10 then 10000 when lvl<=20 then 11500 when lvl<=30 then 13500 when lvl<=40 then 16500 else 20000 end\nfrom (values ('resources'),('workers'),('transport')) v(op) cross join generate_series(1,50) lvl\non conflict (operation_type, level) do nothing;\n\ncreate or replace function public.ng_infrastructure_snapshot()\nreturns jsonb\nlanguage sql\nstable\nsecurity invoker\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'resources', coalesce(ui.resources_level,1),\n    'workers', coalesce(ui.workers_level,1),\n    'transport', coalesce(ui.transport_level,1),\n    'resources_capacity', coalesce((select capacity from ng_infrastructure_levels where operation_type='resources' and level=coalesce(ui.resources_level,1)),1000),\n    'workers_capacity', coalesce((select capacity from ng_infrastructure_levels where operation_type='workers' and level=coalesce(ui.workers_level,1)),1),\n    'transport_capacity', coalesce((select capacity from ng_infrastructure_levels where operation_type='transport' and level=coalesce(ui.transport_level,1)),100)\n  )\n  from public.ng_user_infrastructure ui\n  where ui.user_id = auth.uid();\n$$;\n\n-- RLS\nalter table public.ng_infrastructure_levels enable row level security;\nalter table public.ng_user_infrastructure enable row level security;\ndrop policy if exists ng_infrastructure_levels_read on public.ng_infrastructure_levels;\ncreate policy ng_infrastructure_levels_read on public.ng_infrastructure_levels for select to authenticated using (active = true);\ndrop policy if exists ng_user_infrastructure_self on public.ng_user_infrastructure;\ncreate policy ng_user_infrastructure_self on public.ng_user_infrastructure for select to authenticated using (user_id = (select auth.uid()));\n\nrevoke all on public.ng_infrastructure_levels from anon;\nrevoke all on public.ng_user_infrastructure from anon;\nrevoke all on function public.ng_infrastructure_snapshot() from anon;\ngrant select on public.ng_infrastructure_levels to authenticated;\ngrant select on public.ng_user_infrastructure to authenticated;\ngrant execute on function public.ng_infrastructure_snapshot() to authenticated;\n''')

# docs
(root/'INFRASTRUCTURE_SYSTEM.md').write_text('''# NextGen Miner — Infrastructure System\n\nResources, Workers, and Transport are independent level 1–50 systems.\n\n- Common: levels 1–10\n- Uncommon: levels 11–20\n- Rare: levels 21–30\n- Epic: levels 31–40\n- Legendary: levels 41–50\n\nEach system has its own capacity, cost, artwork, and progression. The selected miner remains the production source; infrastructure upgrades control the operating ceiling and efficiency.\n\n## Upgrade flow\n\nLevel 1 is the starting tier. Level N unlocks only after Level N-1 is owned. Purchases are made with Credit and must be executed server-side.\n\n## Roles\n\nResources = material/storage capacity.\nWorkers = workforce capacity.\nTransport = logistics/delivery capacity.\n\nThe production engine should use the lowest applicable capacity/efficiency as the bottleneck rather than inventing extra rewards.\n''')

# zip
zip_path=Path('/mnt/data/nextgen-miner-final-infrastructure-system.zip')
with zipfile.ZipFile(zip_path,'w',zipfile.ZIP_DEFLATED) as z:
    for f in root.rglob('*'):
        if f.is_file():
            z.write(f, f.relative_to(root.parent))
print(zip_path)
